import { Flex } from '@docs-front/ui';
import MainPrompt from '@/routes/_authenticated/c/-components/MainPrompt/MainPrompt';
import {
  StyledMain,
  StyledRecentDraftTitle
} from '@/routes/_authenticated/c/-index.style';
import { createFileRoute } from '@tanstack/react-router';
import { useI18n } from '@/hooks/useI18n';
import { Suspense, useState } from 'react';
import { useBreakPoints } from '@/hooks/useBreakPoints';
import { useSuspenseQuery } from '@tanstack/react-query';
import { TitleToggle } from '@/routes/_authenticated/c/-components/TitleToggle/TitleToggle';
import RecentDraftList from '@/routes/_authenticated/c/-components/RecentDraftList/RecentDraftList';
import { getProductsQueryOptions } from '@/query/options/products';

export const Route = createFileRoute('/_authenticated/c/')({
  component: RouteComponent
});

function RouteComponent() {
  const { isMobile } = useBreakPoints();
  const { t } = useI18n(['main']);
  const [toggleValue, setToggleValue] = useState<'left' | 'right'>('left');
  const { data: products } = useSuspenseQuery(getProductsQueryOptions());

  const hasProducts = products.length > 0;

  return (
    <Flex
      direction="column"
      height={isMobile ? '100vh' : ''}
      width="100%"
      gap={24}
    >
      <StyledMain $isMobile={isMobile}>
        <Suspense>
          <TitleToggle
            toggleValue={toggleValue}
            onToggleChange={setToggleValue}
          />
        </Suspense>
        <MainPrompt />
        {hasProducts && (
          <Flex
            semantic="section"
            padding="84px 0px"
            direction="column"
            width="100%"
            height="25%"
          >
            <StyledRecentDraftTitle>
              {t('main:recentDraftList.title')}
            </StyledRecentDraftTitle>
            <Suspense>
              <RecentDraftList />
            </Suspense>
          </Flex>
        )}
      </StyledMain>
    </Flex>
  );
}
